INSERT INTO subjects(subject_name,description) VALUES ('Java OOP','Core Java concepts used to design clear, reusable programs');
INSERT INTO subjects(subject_name,description) VALUES ('DBMS and SQL','Relational database design and everyday SQL queries');
INSERT INTO topics(subject_id,topic_name,description) VALUES (1,'Classes and Objects','The building blocks of object-oriented Java programs');
INSERT INTO topics(subject_id,topic_name,description) VALUES (2,'Primary and Foreign Keys','Rules that keep related data accurate and connected');
INSERT INTO learning_material(topic_id,content) VALUES (1,'A class is a blueprint that describes data and behaviour. An object is a real instance created from that blueprint.\n\nExample: a Student class can contain name and email fields, while each Student object has its own values.\n\nImportant points: keep fields private, use methods to control access, and create objects with constructors. Revision question: what is the difference between a class and an object?');
INSERT INTO learning_material(topic_id,content) VALUES (2,'A primary key uniquely identifies each row in a table. A foreign key stores the primary-key value of a related table.\n\nExample: topics.subject_id points to subjects.subject_id, so every topic belongs to a real subject.\n\nImportant points: primary keys are unique and not null, and foreign keys protect relationships. Revision question: why should an attempt store a user_id?');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (1,'What is an object in Java?','MCQ','B',1,'An object is an instance created from a class.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (1,'Which keyword creates an object?','MCQ','A',1,'The new keyword allocates and creates an object.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (1,'Which access modifier best supports encapsulation for fields?','MCQ','C',1,'Fields are usually private and exposed through methods.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (1,'A constructor is mainly used to:','MCQ','D',1,'A constructor initializes a newly created object.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (1,'Which statement is true?','MCQ','B',1,'One class can create many different objects.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (2,'What is the purpose of a primary key?','MCQ','A',1,'It identifies each table row uniquely.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (2,'A foreign key normally references:','MCQ','C',1,'It references a primary key in another table.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (2,'Which rule prevents duplicate email addresses in users?','MCQ','B',1,'The UNIQUE constraint prevents duplicate values.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (2,'Which relationship is subjects to topics?','MCQ','D',1,'One subject can have many topics.');
INSERT INTO questions(topic_id,question_text,question_type,correct_answer,marks,explanation) VALUES (2,'Which SQL clause combines related tables?','MCQ','A',1,'JOIN is used to combine related table rows.');
